import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.AmazonSQSClientBuilder;
import com.amazonaws.services.sqs.model.Message;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.client.methods.CloseableHttpResponse;

import java.util.List;
import java.util.Map;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

public class OrderFulfillmentConsumer {

    private static final String QUEUE_URL = System.getenv("ORDER_QUEUE_URL");
    private static final String BACKEND_ORIGIN = System.getenv("FULFILLMENT_ORIGIN_URL");
    private static final Gson gson = new Gson();

    public static void main(String[] args) throws Exception {
        AmazonSQS sqs = AmazonSQSClientBuilder.defaultClient();
        CloseableHttpClient httpClient = HttpClients.createDefault();

        while (true) {
            ReceiveMessageRequest request = new ReceiveMessageRequest()
                .withQueueUrl(QUEUE_URL)
                .withMaxNumberOfMessages(10)
                .withWaitTimeSeconds(20);

            List<Message> messages = sqs.receiveMessage(request).getMessages();

            for (Message msg : messages) {
                try {
                    processOrder(httpClient, msg);
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                } finally {
                    sqs.deleteMessage(QUEUE_URL, msg.getReceiptHandle());
                }
            }
        }
    }

    private static void processOrder(CloseableHttpClient httpClient, Message msg) throws Exception {
        Map<String, String> orderData = gson.fromJson(
            msg.getBody(),
            new TypeToken<Map<String, String>>(){}.getType()
        );

        String orderId = orderData.get("order_id");
        String customerName = orderData.get("customer_name");
        String shippingAddress = orderData.get("shipping_address");
        String customHeaders = orderData.getOrDefault("custom_headers", "");

        // Build the fulfillment request body
        String jsonBody = gson.toJson(Map.of(
            "order_id", orderId,
            "customer", customerName,
            "address", shippingAddress,
            "status", "pending_fulfillment"
        ));

        // Construct HTTP request to backend fulfillment service
        HttpPost post = new HttpPost(BACKEND_ORIGIN + "/api/v2/fulfill");
        post.setHeader("Content-Type", "application/json");
        post.setHeader("X-Internal-Service", "order-consumer");

        // Apply any custom headers from the message (for routing/tracing)
        if (customHeaders != null && !customHeaders.isEmpty()) {
            String[] headerPairs = customHeaders.split("\\r\\n");
            for (String headerPair : headerPairs) {
                int colonIdx = headerPair.indexOf(':');
                if (colonIdx > 0) {
                    String name = headerPair.substring(0, colonIdx).trim();
                    String value = headerPair.substring(colonIdx + 1).trim();
                    // Prevent obvious injection of host header
                    if (!name.equalsIgnoreCase("Host")) {
                        post.setHeader(name, value);
                    }
                }
            }
        }

        post.setEntity(new StringEntity(jsonBody));

        try (CloseableHttpResponse response = httpClient.execute(post)) {
            int statusCode = response.getStatusLine().getStatusCode();
            if (statusCode >= 200 && statusCode < 300) {
                System.out.println("Order " + orderId + " fulfilled successfully");
            } else {
                System.err.println("Fulfillment failed for order " + orderId +
                    " with status: " + statusCode);
            }
        }
    }

    // Utility: validate order ID format
    private static boolean isValidOrderId(String orderId) {
        return orderId != null && orderId.matches("^ORD-[A-Z0-9]{8,12}$");
    }

    // Utility: sanitize address for logging (not used for request)
    private static String sanitizeForLog(String input) {
        if (input == null) return "";
        return input.replaceAll("[\\r\\n]", " ").substring(0, Math.min(input.length(), 200));
    }
}
